//! The public OWPML element/attribute dictionary (catalog MT-13).
//!
//! `document.validate` compares a document against the element and attribute
//! names of Hancom's public OWPML model (`hancom-io/hwpx-owpml-model`,
//! Apache-2.0, Copyright 2022 Hancom Inc.) instead of against HAE's own rules.
//! Only *names* are taken from the model; no model code is copied, and the
//! dictionary is not a schema: a name that is missing is reported, never
//! repaired or refused.
//!
//! `data/owpml-dictionary.json` is generated by `scripts/owpml_dictionary.py`
//! from a model checkout. Provenance (`sourceRevision`, per-element source
//! file) and the element-name fingerprint live in the file itself; see
//! `docs/decisions/document-validate-2026-10-19.md` for the extraction rules
//! and the evidence behind the report severities.

use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::sync::OnceLock;

/// Bundled dictionary, generated from the model revision named inside it.
pub const DICTIONARY_JSON: &str = include_str!("../data/owpml-dictionary.json");
/// Upstream project the element/attribute names come from.
pub const SOURCE: &str = "hancom-io/hwpx-owpml-model";
pub const SOURCE_LICENSE: &str = "Apache-2.0";

/// Namespace URIs that real HWPX documents bind to a model namespace but that
/// differ from the model's own table. `http://www.idpf.org/2007/opf` (no
/// trailing slash) is what `tests/fixtures/corpus/irb-sample.hwpx` and six
/// other corpus documents bind for the package file; the model table has the
/// trailing-slash form. The alias only selects the prefix used to look names
/// up, so a document keeps its own namespace string in every report.
const URI_ALIASES: &[(&str, &str)] = &[("http://www.idpf.org/2007/opf", "opf")];

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawNamespace {
    prefix: String,
    uri: String,
}

#[derive(Debug, Deserialize)]
struct RawElement {
    ns: String,
    name: String,
    #[serde(default)]
    classes: Vec<String>,
    #[serde(default)]
    files: Vec<String>,
    #[serde(default)]
    ids: Vec<String>,
    #[serde(default)]
    attributes: Vec<String>,
    #[serde(default)]
    children: Vec<String>,
    #[serde(default)]
    root: bool,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawDictionary {
    extractor_version: String,
    source_revision: String,
    namespaces: Vec<RawNamespace>,
    elements: Vec<RawElement>,
    #[serde(default)]
    unresolved: Vec<String>,
    element_fingerprint: String,
}

/// One element name of the model. A name may be registered by several classes
/// (the model keys children by parent class, and for example `hp:offset` is both
/// a character-shape offset and a page-border offset), so the attribute and
/// child sets are the union over every registration.
#[derive(Debug, Clone)]
pub struct Element {
    /// Model namespace prefix (`hh`, `hp`, `hc`, ...).
    pub prefix: String,
    pub name: String,
    /// C++ classes that register the name.
    pub classes: Vec<String>,
    /// Source files (relative to the model root) that register it.
    pub files: Vec<String>,
    /// Model element ids (`ID_PARA_TableType`) from the registrations.
    pub ids: Vec<String>,
    /// Attributes the registering class chains read or write, names only.
    pub attributes: BTreeSet<String>,
    /// `prefix:name` of the children the class chains declare.
    pub children: BTreeSet<String>,
    /// Element names itself with `SetElemName`, i.e. it is a part root.
    pub root: bool,
}

/// The bundled model dictionary.
#[derive(Debug)]
pub struct Dictionary {
    extractor_version: String,
    source_revision: String,
    fingerprint: String,
    /// Model order (prefix, uri) pairs.
    namespaces: Vec<(String, String)>,
    uri_prefix: BTreeMap<String, String>,
    by_key: HashMap<(String, String), usize>,
    elements: Vec<Element>,
}

impl Dictionary {
    /// The bundled dictionary, parsed once per process.
    pub fn get() -> &'static Dictionary {
        static DICT: OnceLock<Dictionary> = OnceLock::new();
        DICT.get_or_init(|| {
            Dictionary::parse(DICTIONARY_JSON).expect("bundled OWPML dictionary parses")
        })
    }

    fn parse(json: &str) -> Result<Dictionary, String> {
        let raw: RawDictionary = serde_json::from_str(json).map_err(|e| e.to_string())?;
        let mut namespaces = Vec::new();
        let mut uri_prefix = BTreeMap::new();
        for ns in raw.namespaces {
            uri_prefix.insert(ns.uri.clone(), ns.prefix.clone());
            namespaces.push((ns.prefix, ns.uri));
        }
        for (uri, prefix) in URI_ALIASES {
            uri_prefix
                .entry((*uri).to_string())
                .or_insert_with(|| (*prefix).to_string());
        }
        let mut elements = Vec::with_capacity(raw.elements.len());
        for e in raw.elements {
            elements.push(Element {
                prefix: e.ns,
                name: e.name,
                classes: e.classes,
                files: e.files,
                ids: e.ids,
                attributes: e.attributes.into_iter().collect(),
                children: e.children.into_iter().collect(),
                root: e.root,
            });
        }
        let mut by_key = HashMap::with_capacity(elements.len());
        for (i, e) in elements.iter().enumerate() {
            by_key.insert((e.prefix.clone(), e.name.clone()), i);
        }
        if !raw.unresolved.is_empty() {
            return Err(format!(
                "dictionary has {} unresolved element registrations",
                raw.unresolved.len()
            ));
        }
        Ok(Dictionary {
            extractor_version: raw.extractor_version,
            source_revision: raw.source_revision,
            fingerprint: raw.element_fingerprint,
            namespaces,
            uri_prefix,
            by_key,
            elements,
        })
    }

    /// Model prefix for a namespace URI bound by a document.
    pub fn prefix_for(&self, uri: &str) -> Option<&str> {
        self.uri_prefix.get(uri).map(String::as_str)
    }

    /// The `(prefix, uri)` table exactly as the model declares it.
    pub fn namespaces(&self) -> &[(String, String)] {
        &self.namespaces
    }

    /// Element record for a `prefix:local` name.
    pub fn element(&self, prefix: &str, local: &str) -> Option<&Element> {
        self.by_key
            .get(&(prefix.to_string(), local.to_string()))
            .map(|&i| &self.elements[i])
    }

    /// Does the model register any element in this namespace? Namespaces such
    /// as `hp10`, `hm`, `dc` and `epub` are declared but empty, so a document
    /// using them is reported as out of coverage, not as unknown names.
    pub fn covered(&self, prefix: &str) -> bool {
        self.elements.iter().any(|e| e.prefix == prefix)
    }

    /// Every `(prefix, name)` pair in the data file's order (sorted by prefix,
    /// then name). The extractor's fingerprint hashes exactly these pairs.
    pub fn element_names(&self) -> impl Iterator<Item = (&str, &str)> {
        self.elements
            .iter()
            .map(|e| (e.prefix.as_str(), e.name.as_str()))
    }

    pub fn element_count(&self) -> usize {
        self.elements.len()
    }

    pub fn namespace_count(&self) -> usize {
        self.namespaces.len()
    }

    pub fn source_revision(&self) -> &str {
        &self.source_revision
    }

    pub fn extractor_version(&self) -> &str {
        &self.extractor_version
    }

    pub fn fingerprint(&self) -> &str {
        &self.fingerprint
    }
}
